-- Restore the organization settings from the nightly dump (row as of 2026-09-29 17:13 UTC) WITHOUT losing
-- anything written since. It MERGES rather than replaces:
--   * every key the live row holds with a real value (e.g. quick_actions) is kept as it is now;
--   * a key the live row is missing, or holds as null / blank text, is filled from the dump.
-- Running it twice gives the same result. If the dump text below is not valid JSON, json_each fails and the
-- statement writes nothing. updated_at is set to NOW so no browser holding an older version can pass If-Match.
--
-- Back up the live row first, so this can be undone:
--   npx wrangler d1 execute hrms --remote --json --command "SELECT key, value, updated_at FROM settings WHERE key = 'organization'" > org-settings-before.json
-- Run:
--   npx wrangler d1 execute hrms --remote --file=org-settings.sql
-- Expect "changes": 1.
WITH
  dump(v) AS (SELECT '{"name":"Metasphere","legal_name":"Metasphere IT Services LLP","logo":"data:image/svg+xml;base64,","logo_dark":"data:image/svg+xml;base64,","wordmark":"data:image/svg+xml;base64,","wordmark_dark":"data:image/svg+xml;base64,","favicon":"data:image/svg+xml;base64,","logo_text":"Metasphere","name_font":"rounded","name_weight":"bold","name_size":"large","address":"A - 635/636 Money Plant High Street\nJagatpur Road, S.G. Highway, Gota\nAhmedabad, Gujarat - 382470","incorporation_date":"2024-10-10","default_department":null,"primary_color":"#1D4C91","email_logo_url":"https://cdn.msphere.io/logo-64px.png","document_logos":{},"currencies":["INR"],"default_currency":"INR","currency_decimals":{"INR":0},"banks":[]}'),
  live(v) AS (SELECT "value" FROM "settings" WHERE "key" = 'organization'),
  -- Live keys that hold something: these win.
  keep AS (
    SELECT j.key, j.type, j.value FROM live, json_each(live.v) AS j
    WHERE NOT (j.type = 'null' OR (j.type = 'text' AND trim(j.value) = ''))
  ),
  -- Dump keys the live row has no real value for.
  fill AS (
    SELECT j.key, j.type, j.value FROM dump, json_each(dump.v) AS j
    WHERE j.key NOT IN (SELECT key FROM keep)
  ),
  merged AS (SELECT * FROM keep UNION ALL SELECT * FROM fill)
INSERT INTO "settings" ("key", "value", "updated_at")
SELECT
  'organization',
  json_group_object(key, json(CASE type
    WHEN 'true' THEN 'true'
    WHEN 'false' THEN 'false'
    WHEN 'null' THEN 'null'
    WHEN 'object' THEN value
    WHEN 'array' THEN value
    ELSE json_quote(value)
  END)),
  CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
FROM merged
WHERE true -- required by SQLite's parser for an upsert whose source is a SELECT
ON CONFLICT ("key") DO UPDATE SET "value" = excluded."value", "updated_at" = excluded."updated_at";